-- ================================================================
-- TJSP (1º grau): fóruns, varas e Juizados — adicionado em 30/09/2026.
-- Fonte: Lista Telefônica pública do TJSP (tjsp.jus.br/ListaTelefonica), coletada em 30/09/2026.
-- ~460 fóruns e ~1.960 varas com endereço, telefone e e-mail (o que o TJSP informa).
-- SEM ids fixos: confere por endereço e nome, então é SEGURO reaplicar a cada atualização
-- (atualizar_aws_remote.sh) — onde o TJSP já existe não faz nada, e numa instalação nova
-- cadastra tudo. Mesma lógica do "S9 - 2026-09-30_varas_tjsp.sql" (aplicado em LOCAL, Antônio e Erick).
-- Regras: só varas/Juizados (sem ofícios/cartórios); "Juiz Titular/Auxiliar" = 1 vara; desativados fora;
-- codVaraNoProc, complemento da vara e dados não informados pelo TJSP ficam NULL.
-- ================================================================
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_vara_tjsp;
DROP TEMPORARY TABLE IF EXISTS tmp_forum_tjsp;

CREATE TEMPORARY TABLE tmp_forum_tjsp (
  k INT NOT NULL,
  nome VARCHAR(150) NOT NULL,
  abrev_nome VARCHAR(50) DEFAULT NULL,
  cidade VARCHAR(100) DEFAULT NULL,
  cep VARCHAR(8) DEFAULT NULL,
  logradouro VARCHAR(300) DEFAULT NULL,
  num_end VARCHAR(11) DEFAULT NULL,
  compl_end VARCHAR(50) DEFAULT NULL,
  bairro VARCHAR(100) DEFAULT NULL,
  uf VARCHAR(2) DEFAULT NULL,
  cep_existente VARCHAR(8) DEFAULT NULL,
  num_existente VARCHAR(20) DEFAULT NULL,
  existia TINYINT NOT NULL DEFAULT 0,
  forum_id INT DEFAULT NULL,
  PRIMARY KEY (k)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TEMPORARY TABLE tmp_vara_tjsp (
  forum_k INT NOT NULL,
  nome VARCHAR(150) NOT NULL,
  abrev_nome VARCHAR(50) DEFAULT NULL,
  tel VARCHAR(50) DEFAULT NULL,
  email VARCHAR(100) DEFAULT NULL,
  pular_se_forum_existia TINYINT NOT NULL DEFAULT 0,
  KEY (forum_k)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

