-- Passo 1: reconhece os fóruns do TJSP que já existem no banco (cadastrados à mão), pelo CEP + número do endereço.
UPDATE tmp_forum_tjsp t
SET t.forum_id = (
  SELECT MIN(f.id) FROM tblforum f
  WHERE f.cep = t.cep_existente
    AND (CASE WHEN f.num_end REGEXP '[0-9]' THEN REGEXP_REPLACE(f.num_end, '[^0-9]', '') ELSE LOWER(TRIM(f.num_end)) END) = t.num_existente
)
WHERE t.cep_existente IS NOT NULL;

-- Marca os fóruns que já existiam no banco antes deste script.
UPDATE tmp_forum_tjsp SET existia = 1 WHERE forum_id IS NOT NULL;

-- Passo 2: fórum já carregado por este mesmo script antes (mesmo nome e mesmo endereço) -> reaproveita.
UPDATE tmp_forum_tjsp t
SET t.forum_id = (
  SELECT MIN(f.id) FROM tblforum f
  WHERE f.nome = t.nome
    AND IFNULL(f.cep, '') = IFNULL(t.cep, '')
    AND IFNULL(f.num_end, '') = IFNULL(t.num_end, '')
)
WHERE t.forum_id IS NULL;

-- Passo 3: cadastra os fóruns que ainda não existem.
INSERT INTO tblforum (abrev_nome, nome, cidade, cep, logradouro, num_end, compl_end, bairro, uf, ativo, criado_por)
SELECT t.abrev_nome, t.nome, t.cidade, t.cep, t.logradouro, t.num_end, t.compl_end, t.bairro, t.uf, 1, NULL
FROM tmp_forum_tjsp t
WHERE t.forum_id IS NULL
ORDER BY t.k;
SET @foruns_novos = ROW_COUNT();

-- Passo 4: descobre o id dos fóruns recém-criados.
UPDATE tmp_forum_tjsp t
SET t.forum_id = (
  SELECT MIN(f.id) FROM tblforum f
  WHERE f.nome = t.nome
    AND IFNULL(f.cep, '') = IFNULL(t.cep, '')
    AND IFNULL(f.num_end, '') = IFNULL(t.num_end, '')
)
WHERE t.forum_id IS NULL;

-- Passo 5: cadastra as varas que ainda não existem no fórum (mesmo nome no mesmo fórum = ignora).
INSERT INTO tblvara (abrev_nome, forum_id, nome, codVaraNoProc, compl_end, tel, email, ativo, criado_por)
SELECT v.abrev_nome, t.forum_id, v.nome, NULL, NULL, v.tel, v.email, 1, NULL
FROM tmp_vara_tjsp v
JOIN tmp_forum_tjsp t ON t.k = v.forum_k
WHERE t.forum_id IS NOT NULL
  AND NOT (v.pular_se_forum_existia = 1 AND t.existia = 1)
  AND NOT EXISTS (SELECT 1 FROM tblvara x WHERE x.forum_id = t.forum_id AND x.nome = v.nome)
ORDER BY v.forum_k, v.nome;
SET @varas_novas = ROW_COUNT();

COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_vara_tjsp;
DROP TEMPORARY TABLE IF EXISTS tmp_forum_tjsp;

